with Path('CLAIMS.jsonl').open('w',encoding='utf8') as f:
 for claim,status,loc,gap,checks in claims:f.write(json.dumps(dict(problem_id='C0100',claim=claim,status=status,proof_location=loc,remaining_gap=gap,checks=checks),ensure_ascii=False)+'\n')
p=Path('ATTEMPT.md');s=p.read_text(encoding='utf8').replace('It formalizes the factorial-moment inversion and a mass/mean-preserving direction over Q.','It formalizes the factorial-moment inversion, a mass/mean-preserving direction over Q, and the exhaustive factorial-moment table for the four heights via decide +kernel.');p.write_text(s,encoding='utf8')
